from sympy import sqrt, cos, sin, Rational, pi, simplify, csc, sec
for A in [pi/7, pi/5, Rational(1,3)]:
    e=sqrt((1-cos(A))/(1+cos(A)))+sqrt((1+cos(A))/(1-cos(A)))
    opts={'A':2*csc(A),'B':2*sec(A),'C':2*cos(A),'D':2*sin(A)}
    assert abs(float(e-opts['A']))<1e-12
    for k in 'BCD':
        assert abs(float(e-opts[k]))>1e-6

from sympy import symbols, solve, Rational
x,y=symbols('x y')
def sol(a):
    s=solve([a*x+(a**2+1)*y-4,4*x+a*y-a**2],[x,y],dict=True)[0]
    return (s[x],s[y])
opts={'A':(6,(48,4)),'B':(-12,(48,4)),'C':(6,(Rational(325,28),Rational(-25,28))),'D':(-12,(Rational(325,28),Rational(-25,28)))}
fit=[k for k,(a,v) in opts.items() if sol(a)==v]
assert fit==['B']
